import{_ as o,o as d,c as t,a3 as a}from"./chunks/framework.BlfGB29P.js";const v=JSON.parse('{"title":"Tenant API v1 — Vendors","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Vendors | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-vendors"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Vendors | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-vendors"}]]},"headers":[],"relativePath":"api/tenant-v1-vendors.md","filePath":"api/tenant-v1-vendors.md","lastUpdated":1786668537000}'),n={name:"api/tenant-v1-vendors.md"};function s(r,e,c,i,l,h){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-vendors" tabindex="-1">Tenant API v1 — Vendors <a class="header-anchor" href="#tenant-api-v1-—-vendors" aria-label="Permalink to &quot;Tenant API v1 — Vendors&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:vendors</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>vendors.assign</code> (and not superadmin), list/stats/view/update only include vendors where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-vendors-stats" tabindex="-1">GET <code>/vendors/stats</code> <a class="header-anchor" href="#get-vendors-stats" aria-label="Permalink to &quot;GET `/vendors/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_vendors</code>, <code>my_vendors</code>, <code>unassigned</code>, <code>active</code>, <code>inactive</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="vendors-crud" tabindex="-1">Vendors CRUD <a class="header-anchor" href="#vendors-crud" aria-label="Permalink to &quot;Vendors CRUD&quot;">​</a></h2><h3 id="get-vendors" tabindex="-1">GET <code>/vendors</code> <a class="header-anchor" href="#get-vendors" aria-label="Permalink to &quot;GET `/vendors`&quot;">​</a></h3><p>Query: <code>search</code> (matches name, email, phone, website, address, tax_id), <code>status</code> (<code>active</code>|<code>inactive</code>), <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_vendors</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>latest_note</code> — most recent note (<code>id</code>, <code>body</code>, <code>author</code>, timestamps) or <code>null</code>.</p><h3 id="post-vendors" tabindex="-1">POST <code>/vendors</code> <a class="header-anchor" href="#post-vendors" aria-label="Permalink to &quot;POST `/vendors`&quot;">​</a></h3><p>Body: <code>name</code> (required), <code>email</code>, <code>phone</code>, <code>website</code>, <code>address</code>, <code>tax_id</code>, <code>payment_terms</code>, <code>currency</code> (max 3 chars), <code>status</code> (<code>active</code>|<code>inactive</code>, defaults to <code>active</code>), <code>assigned_to</code>.</p><h3 id="get-vendors-id" tabindex="-1">GET <code>/vendors/{id}</code> <a class="header-anchor" href="#get-vendors-id" aria-label="Permalink to &quot;GET `/vendors/{id}`&quot;">​</a></h3><p>Includes assignee, creator, notes, and activities.</p><h3 id="put-vendors-id" tabindex="-1">PUT <code>/vendors/{id}</code> <a class="header-anchor" href="#put-vendors-id" aria-label="Permalink to &quot;PUT `/vendors/{id}`&quot;">​</a></h3><p>Partial update of vendor fields (including <code>assigned_to</code>).</p><h3 id="delete-vendors-id" tabindex="-1">DELETE <code>/vendors/{id}</code> <a class="header-anchor" href="#delete-vendors-id" aria-label="Permalink to &quot;DELETE `/vendors/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>vendors.delete</code>.</p><h3 id="post-vendors-id-restore" tabindex="-1">POST <code>/vendors/{id}/restore</code> <a class="header-anchor" href="#post-vendors-id-restore" aria-label="Permalink to &quot;POST `/vendors/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted vendor. Permission: <code>vendors.restore</code>.</p><h3 id="delete-vendors-id-force" tabindex="-1">DELETE <code>/vendors/{id}/force</code> <a class="header-anchor" href="#delete-vendors-id-force" aria-label="Permalink to &quot;DELETE `/vendors/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted vendor (must already be trashed). Permission: <code>vendors.force.delete</code> (owner by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-vendors-id-assign" tabindex="-1">POST <code>/vendors/{id}/assign</code> <a class="header-anchor" href="#post-vendors-id-assign" aria-label="Permalink to &quot;POST `/vendors/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><h3 id="post-vendors-id-notes" tabindex="-1">POST <code>/vendors/{id}/notes</code> <a class="header-anchor" href="#post-vendors-id-notes" aria-label="Permalink to &quot;POST `/vendors/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-vendors-id-timeline" tabindex="-1">GET <code>/vendors/{id}/timeline</code> <a class="header-anchor" href="#get-vendors-id-timeline" aria-label="Permalink to &quot;GET `/vendors/{id}/timeline`&quot;">​</a></h3><p>Vendor activity timeline entries.</p>',31)])])}const m=o(n,[["render",s]]);export{v as __pageData,m as default};
